using Microsoft.EntityFrameworkCore;

namespace HumanitarianCrisis.API.Data;

/// <summary>Creates just the new notification table for databases originally created with EnsureCreated.</summary>
public static class NotificationSchema
{
    public static async Task EnsureAsync(CrisisDbContext db, CancellationToken cancellationToken = default)
    {
        var provider = db.Database.ProviderName ?? string.Empty;
        var sql = provider switch
        {
            "Microsoft.EntityFrameworkCore.SqlServer" => "IF OBJECT_ID(N'[dbo].[Notifications]', N'U') IS NULL CREATE TABLE [dbo].[Notifications] ([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY, [RecipientAccountId] int NULL, [Recipient] nvarchar(254) NOT NULL, [RecipientName] nvarchar(150) NOT NULL, [Channel] nvarchar(10) NOT NULL, [Subject] nvarchar(200) NOT NULL, [Message] nvarchar(4000) NOT NULL, [Status] nvarchar(20) NOT NULL, [Attempts] int NOT NULL, [LastError] nvarchar(500) NULL, [CreatedByAccountId] int NOT NULL, [CreatedByName] nvarchar(150) NOT NULL, [CreatedAt] datetime2 NOT NULL, [SentAt] datetime2 NULL, [ReadAt] datetime2 NULL); IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_Notifications_RecipientAccountId_CreatedAt') CREATE INDEX [IX_Notifications_RecipientAccountId_CreatedAt] ON [dbo].[Notifications] ([RecipientAccountId], [CreatedAt]);",
            "Npgsql.EntityFrameworkCore.PostgreSQL" => "CREATE TABLE IF NOT EXISTS \"Notifications\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"RecipientAccountId\" integer NULL, \"Recipient\" varchar(254) NOT NULL, \"RecipientName\" varchar(150) NOT NULL, \"Channel\" varchar(10) NOT NULL, \"Subject\" varchar(200) NOT NULL, \"Message\" varchar(4000) NOT NULL, \"Status\" varchar(20) NOT NULL, \"Attempts\" integer NOT NULL, \"LastError\" varchar(500) NULL, \"CreatedByAccountId\" integer NOT NULL, \"CreatedByName\" varchar(150) NOT NULL, \"CreatedAt\" timestamp with time zone NOT NULL, \"SentAt\" timestamp with time zone NULL, \"ReadAt\" timestamp with time zone NULL); CREATE INDEX IF NOT EXISTS \"IX_Notifications_RecipientAccountId_CreatedAt\" ON \"Notifications\" (\"RecipientAccountId\", \"CreatedAt\");",
            _ => "CREATE TABLE IF NOT EXISTS \"Notifications\" (\"Id\" INTEGER NOT NULL CONSTRAINT \"PK_Notifications\" PRIMARY KEY AUTOINCREMENT, \"RecipientAccountId\" INTEGER NULL, \"Recipient\" TEXT NOT NULL, \"RecipientName\" TEXT NOT NULL, \"Channel\" TEXT NOT NULL, \"Subject\" TEXT NOT NULL, \"Message\" TEXT NOT NULL, \"Status\" TEXT NOT NULL, \"Attempts\" INTEGER NOT NULL, \"LastError\" TEXT NULL, \"CreatedByAccountId\" INTEGER NOT NULL, \"CreatedByName\" TEXT NOT NULL, \"CreatedAt\" TEXT NOT NULL, \"SentAt\" TEXT NULL, \"ReadAt\" TEXT NULL); CREATE INDEX IF NOT EXISTS \"IX_Notifications_RecipientAccountId_CreatedAt\" ON \"Notifications\" (\"RecipientAccountId\", \"CreatedAt\");"
        };
        await db.Database.ExecuteSqlRawAsync(sql, cancellationToken);
    }
}
